import com.comsol.model.*;import com.comsol.model.util.*;
public class InspectDrive{public static void main(String[]a)throws Exception{ModelUtil.initStandalone(true);Model m=ModelUtil.load("m","D:\\comsol_ao_run\\convergence\\Wap_6um_fine_Model.mph");System.out.println("MULTI="+String.join(",",m.multiphysics().tags()));for(String q:m.multiphysics().tags()){try{System.out.println(q+" type="+m.multiphysics(q).getType()+" sel="+java.util.Arrays.toString(m.multiphysics(q).selection().entities()));}catch(Throwable t){}}System.out.println("MAT="+String.join(",",m.component("comp1").material().tags()));for(String p:m.component("comp1").material("matLN").propertyGroup().tags()){System.out.println("PG="+p+" props="+String.join(",",m.component("comp1").material("matLN").propertyGroup(p).properties()));for(String prop:m.component("comp1").material("matLN").propertyGroup(p).properties()){try{System.out.println(prop+"="+java.util.Arrays.deepToString(m.component("comp1").material("matLN").propertyGroup(p).getStringArray(prop)));}catch(Throwable t){}}}ModelUtil.disconnect();}}
